#!/usr/bin/env python3
"""
Read results/*.jsonl from the Modal volume and append new rows to
paper/results_table.tex.  Rows already in the file are not duplicated.

Usage:
    python paper/generate_results.py [--results-dir results] [--paper-dir paper]
"""

import argparse
import json
from pathlib import Path


TABLE_HEADER = """\
% Auto-generated by paper/generate_results.py — do not edit manually.
% Each row is one completed assay run. New rows are appended by generate_results.py.

\\begin{table}[h]
\\centering
\\caption{Assay-level results. $\\rho$: Spearman rank correlation vs.\\ experiment.
$\\beta$: wall\\_s / L$^2$ (s/AA$^2$). Published target: $\\rho = 0.414 \\pm 0.012$.}
\\label{tab:results}
\\begin{tabular}{llrrrrl}
\\toprule
Run date & Assay & $L$ & $N_\\text{var}$ & $\\rho$ & $\\beta$ (s/AA$^2$) & Hardware \\\\
\\midrule
"""

TABLE_FOOTER = """\
\\bottomrule
\\end{tabular}
\\end{table}
"""


def _sci(x):
    if x is None:
        return "---"
    return f"${x:.2e}$".replace("e-0", r"e-").replace("e+0", r"e+")


def _fmt_rho(x):
    if x is None:
        return "---"
    return f"${x:+.3f}$"


def read_jsonl(path: Path) -> list[dict]:
    rows = []
    if not path.exists():
        return rows
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    rows.append(json.loads(line))
                except json.JSONDecodeError:
                    pass
    return rows


def build_rows(results_dir: Path) -> list[dict]:
    rows = []
    for jsonl in sorted(results_dir.glob("*_stream.jsonl")):
        method = jsonl.stem.replace("_stream", "")
        for r in read_jsonl(jsonl):
            if "assay_id" not in r:
                continue
            rows.append({
                "method":     method,
                "assay_id":   r.get("assay_id", ""),
                "L":          r.get("sequence_length", "---"),
                "n_variants": r.get("n_variants", "---"),
                "rho":        r.get("spearman_rho"),
                "beta":       r.get("beta"),
                "hardware":   r.get("hardware", "A100 SXM4"),
                "run_date":   r.get("run_date", "---"),
            })
    return rows


def rows_to_tex(rows: list[dict]) -> str:
    lines = [TABLE_HEADER]
    prev_method = None
    for r in rows:
        if r["method"] != prev_method:
            lines.append(f"% ── {r['method']} ──\n")
            prev_method = r["method"]
        n = f"{r['n_variants']:,}" if isinstance(r["n_variants"], int) else r["n_variants"]
        lines.append(
            f"{r['run_date']} & {r['assay_id']} & {r['L']} & {n} & "
            f"{_fmt_rho(r['rho'])} & {_sci(r['beta'])} & {r['hardware']} \\\\\n"
        )
    lines.append(TABLE_FOOTER)
    return "".join(lines)


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--results-dir", default="results")
    p.add_argument("--paper-dir",   default="paper")
    args = p.parse_args()

    results_dir = Path(args.results_dir)
    out_path    = Path(args.paper_dir) / "results_table.tex"

    rows = build_rows(results_dir)
    if not rows:
        print(f"No JSONL rows found in {results_dir}/ — leaving results_table.tex unchanged.")
        return

    out_path.write_text(rows_to_tex(rows))
    print(f"Wrote {len(rows)} rows → {out_path}")


if __name__ == "__main__":
    main()
